  "adv.be-succession-regions.action": "تحقّق من قواعد منطقتك",
  "adv.be-succession-regions.body": "في بلجيكا، ضريبتا الإرث والهبة من اختصاص المناطق: النسب والإعفاءات تختلف بين فلاندرز ووالونيا وبروكسل، والمعيار هو الموطن الضريبي للمتوفى أو الواهب لا الوارث. قبل أي تخطيط (هبة منقولات أو عقار)، تحقّق من قواعد منطقتك أنت.",
  "adv.be-succession-regions.title": "الإرث والهبة: كل شيء يتوقف على منطقتك",
  "adv.ch-lamal-franchise.fig.1.value": "700 فرنك/سنة",
  "adv.pets-budget-chat.body": "الطعام والفرشة والعناية الاعتيادية (دون التأمين): من 600 إلى 1 000 € سنويًا، أي من 50 إلى 85 €/شهر. خصّص هذا المبلغ في فئة مستقلّة حتى لا تصطدم زيارات الطبيب البيطري بما يتبقّى لك للعيش.",
  "adv.pets-budget-chat.body.multi": "الطعام والفرشة والعناية الاعتيادية (دون التأمين): من 600 إلى 1 000 € سنويًا، أي من 50 إلى 85 €/شهر. خصّص هذا المبلغ في فئة مستقلّة حتى لا تصطدم زيارات الطبيب البيطري بما يتبقّى لك للعيش.",
